package dev.sablelife.testing;
import dev.sablelife.SableLife;import dev.sablelife.heart.*;import dev.sablelife.module.*;import dev.ryanhcode.sable.api.SubLevelAssemblyHelper;import dev.ryanhcode.sable.companion.math.BoundingBox3i;import net.minecraft.core.*;import net.minecraft.gametest.framework.*;import net.minecraft.world.entity.EntityType;import net.minecraft.world.level.block.Blocks;import net.neoforged.neoforge.gametest.*;import java.util.*;
@GameTestHolder("sablelife_control_tests") @PrefixGameTestTemplate(false)
public final class InternalRedstoneGameTests {
 private static HeartBlockEntity core(GameTestHelper h){var l=h.getLevel();var p=h.absolutePos(new BlockPos(4,40,4));l.setBlockAndUpdate(p,SableLife.HEART.get().defaultBlockState());l.setBlockAndUpdate(p.east(),Blocks.IRON_BLOCK.defaultBlockState());var b=SubLevelAssemblyHelper.assembleBlocks(l,p,List.of(p,p.east()),new BoundingBox3i(p.getX(),p.getY(),p.getZ(),p.getX()+1,p.getY(),p.getZ()));var c=(HeartBlockEntity)l.getBlockEntity(b.getPlot().getCenterBlock());for(int i=0;i<3;i++){c.wireless().add();c.wireless().channel(i).set(0,1);c.wireless().channel(i).set(6,3);}return c;}
 private static VirtualModule out(HeartBlockEntity c,int power){var m=c.modules().add("wireless_redstone");m.edit("trigger",0,"");m.edit("redstoneChannel",1,"");m.edit("redstonePower",power,"");m.edit("redstoneFaces",0,"");return m;}
 @GameTest(template="combat",batch="internal_redstone_merge") public static void MarkAndInternalOutputsCoexistAndClearDoesNotEraseOtherSources(GameTestHelper h){var c=core(h);var a=out(c,7);a.anchors(List.of(ModuleAnchor.create(c,c.getBlockPos().east(),Direction.UP)));var b=out(c,12);c.tryActivate(TestActors.creative(h.getLevel()));c.modules().tick(c);h.assertTrue(c.wireless().output(0)==12&&ModuleSignals.signal(h.getLevel(),c.getBlockPos().east(),Direction.DOWN)==7,"Marked/internal destinations or strongest merge failed");b.edit("enabled",0,"");c.modules().tick(c);h.assertTrue(c.wireless().output(0)==7,"Disabled producer retained output");c.wireless().programOutputs("other",Map.of(0,15));var runtime=new ModuleRedstone();runtime.tick(c,new HashMap<>(),Set.of());runtime.clear();h.assertTrue(c.wireless().output(0)==15,"Redstone clear erased another source");c.wireless().programOutputs("other",Map.of());h.assertTrue(c.wireless().output(0)==0,"Internal output survived clear");h.succeed();}
 @GameTest(template="combat",batch="internal_redstone_modes") public static void PulseAndReverseApplyToInternalAndMasterOrDisableStopsOutput(GameTestHelper h){var c=core(h);var m=out(c,9);m.edit("redstoneMode",1,"");m.edit("redstonePulse",3,"");c.tryActivate(TestActors.creative(h.getLevel()));c.modules().tick(c);h.assertTrue(c.wireless().output(0)==9,"Internal pulse did not start");h.runAfterDelay(4,()->{c.modules().tick(c);h.assertTrue(c.wireless().output(0)==0,"Held trigger restarted expired pulse");m.edit("redstoneInvert",1,"");c.modules().tick(c);h.assertTrue(c.wireless().output(0)==9,"Reverse did not restore idle output");m.edit("enabled",0,"");c.modules().tick(c);h.assertTrue(c.wireless().output(0)==0,"Disabled reverse emitted");m.edit("enabled",1,"");c.wireless().master(false);c.modules().tick(c);h.assertTrue(c.wireless().output(0)==0,"Master off emitted reverse");c.wireless().master(true);m.edit("redstoneMode",0,"");m.edit("redstoneInvert",0,"");c.modules().tick(c);h.assertTrue(c.wireless().output(0)==9,"Hold did not resume");c.forceDeath();c.modules().tick(c);h.assertTrue(c.wireless().output(0)==0,"Death retained internal output");h.succeed();});}
 @GameTest(template="combat",batch="internal_redstone_moveset") public static void MoveSetFeedsArmorSecondRuleWithoutSequenceOrMark(GameTestHelper h){var c=core(h);var emitter=out(c,15);emitter.edit("redstoneChannel",2,"");var table=c.modules().add("move_set");table.moveSet().edit("add",0,"",c.modules());table.moveSet().edit("action_add",0,"0|"+emitter.id(),c.modules());table.moveSet().edit("action_duration",1,"0|0",c.modules());table.moveSet().get(0).config().edit("dispatchCooldown",1200,"");var armor=c.modules().add("armor");armor.anchors(List.of(ModuleAnchor.create(c,c.getBlockPos(),Direction.UP)));var first=armor.armorRules().add();first.edit("channel",1);first.edit("modifier",-100);var second=armor.armorRules().add();second.edit("channel",2);second.edit("modifier",-50);var pig=EntityType.PIG.create(h.getLevel());pig.setPos(ModuleArena.corePosition(c).add(3,0,0));pig.setNoAi(true);pig.setNoGravity(true);h.getLevel().addFreshEntity(pig);c.tryActivate(TestActors.creative(h.getLevel()));c.modules().tick(c);h.assertTrue(c.wireless().output(1)==15&&ModuleArmor.damage(c,c.getBlockPos(),20)==10,"Move set did not activate armor rule 2");h.runAfterDelay(22,()->{c.modules().tick(c);h.assertTrue(c.wireless().output(1)==0&&ModuleArmor.damage(c,c.getBlockPos(),20)==20,"Finished move retained protection");pig.discard();h.succeed();});}
 @GameTest(template="combat",batch="internal_redstone_config") public static void ChannelsPersistShiftUnbindAndRejectNonSequenceOutputs(GameTestHelper h){var c=core(h);var m=out(c,15);m.edit("redstoneChannel",3,"");h.assertTrue(VirtualModule.load(m.save()).value("redstoneChannel")==3&&ModulePreset.create(m.save()).value("redstoneChannel")==0&&dev.sablelife.client.NumericWheelSteps.module("wireless_redstone","redstoneChannel",1,0)==1,"Configuration/preset/wheel policy failed");c.wireless().remove(0);h.assertTrue(m.value("redstoneChannel")==2,"Earlier deletion changed destination");c.wireless().remove(1);h.assertTrue(m.value("redstoneChannel")==0,"Deleted destination redirected to another channel");m.edit("redstoneChannel",1,"");c.wireless().channel(0).set(6,0);c.wireless().channel(0).set(2,1);c.wireless().channel(0).set(3,12000);c.tryActivate(TestActors.creative(h.getLevel()));var runtime=new ModuleRedstone();runtime.tick(c,new HashMap<>(),Set.of());h.assertTrue(!ModuleHealthPhase.channelStatus(m,c,"redstoneChannel").equals("ready"),"Normal waveform accepted as module output");c.wireless().channel(0).set(6,3);runtime.tick(c,new HashMap<>(),Set.of());h.assertTrue(c.wireless().output(0)==15,"Sequence channel refused internal output");h.succeed();}
 @GameTest(template="combat",batch="internal_redstone_three_destinations") public static void InternalMarkedAndExternalOutputsWorkTogether(GameTestHelper h){var c=core(h);var m=out(c,9);m.anchors(List.of(ModuleAnchor.create(c,c.getBlockPos().east(),Direction.UP)));var red=new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.NETHER_STAR);var blue=new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.DIAMOND);m.redBlue(false,red,h.getLevel().registryAccess());m.redBlue(true,blue,h.getLevel().registryAccess());int[] power={0};var receiver=new com.simibubi.create.content.redstone.link.IRedstoneLinkable(){public int getTransmittedStrength(){return 0;}public void setReceivedStrength(int n){power[0]=n;}public boolean isListening(){return true;}public boolean isAlive(){return true;}public net.createmod.catnip.data.Couple<com.simibubi.create.content.redstone.link.RedstoneLinkNetworkHandler.Frequency> getNetworkKey(){return net.createmod.catnip.data.Couple.create(com.simibubi.create.content.redstone.link.RedstoneLinkNetworkHandler.Frequency.of(red),com.simibubi.create.content.redstone.link.RedstoneLinkNetworkHandler.Frequency.of(blue));}public BlockPos getLocation(){return c.getBlockPos().east();}};com.simibubi.create.Create.REDSTONE_LINK_NETWORK_HANDLER.addToNetwork(h.getLevel(),receiver);c.tryActivate(TestActors.creative(h.getLevel()));c.modules().tick(c);h.assertTrue(c.wireless().output(0)==9&&power[0]==9&&ModuleSignals.signal(h.getLevel(),c.getBlockPos().east(),Direction.DOWN)==9,"Three destinations did not emit the same strength");m.edit("enabled",0,"");c.modules().tick(c);h.assertTrue(c.wireless().output(0)==0&&power[0]==0&&ModuleSignals.signal(h.getLevel(),c.getBlockPos().east(),Direction.DOWN)==0,"Disabled module retained destination output");com.simibubi.create.Create.REDSTONE_LINK_NETWORK_HANDLER.removeFromNetwork(h.getLevel(),receiver);h.succeed();}

}
